import React from 'react';
import { BrowserRouter as Router, Route, Routes, Link } from 'react-router-dom';
import MotoristasList from './components/MotoristasList';
import BuscarMotorista from './components/BuscarMotorista';
import CadastrarMotorista from './components/CadastrarMotorista';
import './styles/global.css';

const App = () => {
    return (
        <Router>
            <nav className="navbar">
                <h1>CheckPort 🚗</h1>
                <div className="nav-links">
                    <Link to="/">Lista</Link>
                    <Link to="/buscar">Buscar</Link>
                    <Link to="/cadastrar">Cadastrar</Link>
                </div>
            </nav>

            <div className="container">
                <Routes>
                    <Route path="/" element={<MotoristasList />} />
                    <Route path="/buscar" element={<BuscarMotorista />} />
                    <Route path="/cadastrar" element={<CadastrarMotorista />} />
                </Routes>
            </div>
        </Router>
    );
};

export default App;
